from pathlib import Path
import json,sys
sys.stdout.reconfigure(encoding='utf-8')
roots=list(Path('.relay').glob('launch-r3-trial-*/clone'))
if not roots:print('trial_scan_roots',0)
else:
 stats={'files_checked':0,'units_checked':0,'duplicate_keys':0,'malformed_units':0}
 def pairs(items):
  seen=set()
  for k,v in items:
   if k in seen:stats['duplicate_keys']+=1
   seen.add(k)
  return dict(items)
 for p in roots[0].rglob('*'):
  if not p.is_file() or '.git' in p.relative_to(roots[0]).parts or p.suffix not in ['.json','.jsonl','.sse']:continue
  stats['files_checked']+=1;t=p.read_text(encoding='utf-8')
  if p.suffix=='.json':units=[t] if t.strip() else []
  elif p.suffix=='.jsonl':units=[l for l in t.splitlines() if l.strip()]
  else:units=[l[5:].strip() for l in t.splitlines() if l.startswith('data:') and l[5:].strip()"'!='"'[DONE]']
  for u in units:
   stats['units_checked']+=1
   try:json.loads(u,object_pairs_hook=pairs)
   except ValueError:stats['malformed_units']+=1
 print(json.dumps(stats))
 Path('.relay/launch-r3-duplicate-counts.json').write_text(json.dumps(stats),encoding='utf-8')
'@ | python -B -"

